      senior: [{ es: 'Declara la granularidad objetivo', en: 'Declare target grain' }, { es: 'Agrega el detalle antes del join o ajusta granularidad', en: 'Aggregate detail before join or adjust grain' }, { es: 'Valida conteo y totales', en: 'Validate counts and totals' }],
      dwhy: { es: ['La fórmula correcta sobre filas duplicadas sigue duplicando.', 'La corrupción no se presenta como duplicación exacta.', 'El join es la única pieza que multiplica filas.'], en: ['A correct formula over duplicated rows still duplicates.', 'Corruption doesn’t present as exact duplication.', 'The join is the only piece multiplying rows.'], de: ['Formel auf Duplikaten dupliziert.', 'Korruption dupliziert nicht exakt.', 'Nur Join vervielfacht.'] },
