    tips: { es: ['LEFT JOIN + conteo explícito de nulos: la pareja que no miente.', 'Prueba el informe con el caso vacío (sin detalle) desde el diseño.'], en: ['LEFT JOIN + explicit null counting: the pair that doesn’t lie.', 'Test with the empty case (no detail) from design on.'] },
    pf: { es: 'Cambiar inner por left «a ver si así sale» sin contar filas.', en: 'Switching inner to left «let’s see» without counting rows.' },
